export const APPLICATION_STATE_MIGRATION_KEY = 'md2.localStorageMigrationComplete'
export const APPLICATION_STATE_MIGRATION_VALUE = '1'

export const MIGRATED_APPLICATION_STORAGE_KEYS = [
    'md2.actionPromptHeight',
